<?php
require __DIR__.'/../../app/core/bootstrap.php'; $u=require_admin(); require_once __DIR__.'/../../app/helpers/library.php'; require __DIR__.'/../../app/helpers/layout.php';
$error=null;
if(is_post()){
  csrf_check(); $action=$_POST['action']??''; $id=safe_int($_POST['id']??0);
  try{
    if($action==='delete'){
      $st=$pdo->prepare('SELECT cover,file_path,title FROM books WHERE id=?');$st->execute([$id]);$old=$st->fetch();
      if(!$old) throw new RuntimeException('Buku tidak ditemukan.');
      $pdo->prepare('DELETE FROM books WHERE id=?')->execute([$id]); delete_local_upload($old['cover']??null); delete_local_upload($old['file_path']??null);
      log_activity($pdo,safe_int($u['id']),$u['role_name'],'Hapus buku','#'.$id.' '.$old['title']); flash('success','Buku berhasil dihapus.');
    }elseif(in_array($action,['create','update'],true)){
      $title=trim($_POST['title']??'');$author=trim($_POST['author']??'');$isbn=trim($_POST['isbn']??'');$year=trim($_POST['publication_year']??'');$category=safe_int($_POST['category_id']??0);$publisher=safe_int($_POST['publisher_id']??0);$pages=safe_int($_POST['pages']??0);$language=trim($_POST['language']??'Indonesia')?:'Indonesia';$shelf=trim($_POST['shelf_location']??'');$desc=trim($_POST['description']??'');$total=max(1,safe_int($_POST['stock_total']??1));
      if(!$title||!$author) throw new RuntimeException('Judul dan penulis wajib diisi.');
      $cover=null;$pdf=null;$old=null;
      if($action==='update'){ $q=$pdo->prepare('SELECT * FROM books WHERE id=?');$q->execute([$id]);$old=$q->fetch();if(!$old)throw new RuntimeException('Buku tidak ditemukan.'); }
      $cover=save_upload($_FILES['cover']??[],'uploads/books',['jpg','jpeg','png','webp'],5*1024*1024) ?? ($old['cover']??null);
      $pdf=save_upload($_FILES['pdf']??[],'uploads/books',['pdf'],20*1024*1024) ?? ($old['file_path']??null);
      if($action==='create'){
        $st=$pdo->prepare("INSERT INTO books(category_id,publisher_id,isbn,title,author,publication_year,language,pages,shelf_location,description,cover,stock_total,stock_available,status,approval_status,submitted_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?, 'disetujui', NOW())");
        $st->execute([$category?:null,$publisher?:null,$isbn?:null,$title,$author,$year?:null,$language,$pages?:null,$shelf,$desc,$cover,$total,$total,'tersedia']);
        log_activity($pdo,safe_int($u['id']),$u['role_name'],'Tambah buku',$title);flash('success','Buku berhasil ditambahkan.');
      }else{
        $st=$pdo->prepare('UPDATE books SET category_id=?,publisher_id=?,isbn=?,title=?,author=?,publication_year=?,language=?,pages=?,shelf_location=?,description=?,cover=?,file_path=?,stock_total=?,stock_available=LEAST(stock_available,?),status=?,approval_status="disetujui" WHERE id=?');
        $available=min($total,max(0,safe_int($old['stock_available']??$total)));$status=$available>0?'tersedia':'habis';$st->execute([$category?:null,$publisher?:null,$isbn?:null,$title,$author,$year?:null,$language,$pages?:null,$shelf,$desc,$cover,$pdf,$total,$available,$status,$id]);
        if(($cover??null)!==($old['cover']??null))delete_local_upload($old['cover']??null); if(($pdf??null)!==($old['file_path']??null))delete_local_upload($old['file_path']??null);
        log_activity($pdo,safe_int($u['id']),$u['role_name'],'Edit buku','#'.$id.' '.$title);flash('success','Buku berhasil diperbarui.');
      }
    }
    redirect('/admin/books/index.php');
  }catch(Throwable $e){$error='Perubahan buku gagal. Pastikan data valid dan ISBN tidak duplikat.';}
}
$q=trim($_GET['q']??'');$params=[];$sql='SELECT b.*,c.name category,p.name publisher FROM books b LEFT JOIN book_categories c ON c.id=b.category_id LEFT JOIN publishers p ON p.id=b.publisher_id';if($q!==''){$sql.=' WHERE b.title LIKE ? OR b.author LIKE ? OR b.isbn LIKE ?';$like='%'.$q.'%';$params=[$like,$like,$like];}$sql.=' ORDER BY b.id DESC LIMIT 300';$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();$cats=$pdo->query('SELECT id,name FROM book_categories ORDER BY name')->fetchAll();$pubs=$pdo->query('SELECT id,name FROM publishers ORDER BY name')->fetchAll();
render_start('Data Buku','Kelola koleksi buku sebagai Admin',$u);dashboard_nav('admin');render_mid('Data Buku','Tambah, edit, hapus, cari, dan lihat koleksi',$u);if($error):?><div class="alert error" role="alert"><?=e($error)?></div><?php endif; ?>
<div class="card"><div class="toolbar"><div><b>Kelola Buku</b><p class="muted">Buku yang ditambahkan langsung oleh Admin berstatus Disetujui.</p></div><button type="button" class="btn btn-primary" data-open-book-modal>+ Tambah Buku</button></div><form method="get" class="data-toolbar" style="margin-top:16px"><input class="input" name="q" value="<?=e($q)?>" placeholder="Cari judul, penulis, ISBN..."><button class="btn btn-light">Cari</button><a class="btn btn-light" href="/admin/books/index.php">Reset</a><span class="badge">Total <?=count($rows)?> data</span></form></div>
<div class="card" style="margin-top:16px"><div class="table-wrap"><table class="table"><thead><tr><th>Cover</th><th>ID</th><th>Judul</th><th>Penulis</th><th>ISBN</th><th>Kategori</th><th>Stok</th><th>Status</th><th>Aksi</th></tr></thead><tbody>
<?php foreach($rows as $r):?><tr><td><?php if($r['cover']):?><img src="<?=e($r['cover'])?>" class="table-thumb" alt="Cover buku" loading="lazy" decoding="async"><?php else:?><div class="cover-placeholder table-thumb" style="aspect-ratio:auto;font-size:9px;padding:4px">UNCP</div><?php endif;?></td><td>#<?=e($r['id'])?></td><td><b><?=e($r['title'])?></b><div class="muted"><?=e($r['publication_year']??'—')?> · <?=e($r['language']??'Indonesia')?></div></td><td><?=e($r['author'])?></td><td><?=e($r['isbn']??'—')?></td><td><?=e($r['category']??'—')?></td><td><?=e($r['stock_available'])?> / <?=e($r['stock_total'])?></td><td><span class="badge <?=e($r['stock_available']>0?'green':'red')?>"><?=e(book_status(safe_int($r['stock_total']),safe_int($r['stock_available']),$r['status']))?></span></td><td><div class="inline-form"><a class="btn btn-light" href="/pengguna/detail-buku/index.php?id=<?=$r['id']?>">Lihat</a><button type="button" class="btn btn-light" data-edit-book='<?=e(json_encode([
    'id'=>$r['id'],'title'=>$r['title'],'author'=>$r['author'],'isbn'=>$r['isbn']??'',
    'publication_year'=>$r['publication_year']??'','category_id'=>$r['category_id']??'',
    'publisher_id'=>$r['publisher_id']??'','pages'=>$r['pages']??'','language'=>$r['language']??'',
    'shelf_location'=>$r['shelf_location']??'','stock_total'=>$r['stock_total']??1,
    'description'=>$r['description']??''
],JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP|JSON_HEX_TAG))?>'>Edit</button><form method="post" class="inline-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-danger" type="submit" data-confirm="Hapus data buku ini? Data yang telah dihapus tidak dapat dikembalikan.">Hapus</button></form></div></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="9" class="empty">Belum ada data buku.</td></tr><?php endif;?></tbody></table></div></div>
<div class="modal-backdrop" id="bookModal" aria-hidden="true"><div class="confirm-modal modal-shell"><div class="profile-section-title"><div><h2 id="bookModalTitle" style="margin:0">Tambah Buku</h2><p class="muted">Lengkapi informasi koleksi.</p></div><button type="button" class="btn btn-light" data-close-book-modal>×</button></div><form method="post" enctype="multipart/form-data" id="bookForm"><?=csrf_input()?><input type="hidden" name="action" id="bookAction" value="create"><input type="hidden" name="id" id="bookId" value=""><div class="form-grid"><div class="form-group"><label>Judul</label><input class="input" name="title" id="bookTitle" required></div><div class="form-group"><label>Penulis</label><input class="input" name="author" id="bookAuthor" required></div><div class="form-group"><label>ISBN</label><input class="input" name="isbn" id="bookIsbn"></div><div class="form-group"><label>Tahun</label><input class="input" type="number" name="publication_year" id="bookYear" min="1900" max="2100"></div><div class="form-group"><label>Kategori</label><select name="category_id" id="bookCategory"><option value="0">Pilih kategori</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Penerbit</label><select name="publisher_id" id="bookPublisher"><option value="0">Pilih penerbit</option><?php foreach($pubs as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Jumlah Halaman</label><input class="input" type="number" name="pages" id="bookPages" min="1"></div><div class="form-group"><label>Bahasa</label><input class="input" name="language" id="bookLanguage" value="Indonesia"></div><div class="form-group"><label>Lokasi Rak</label><input class="input" name="shelf_location" id="bookShelf"></div><div class="form-group"><label>Stok</label><input class="input" type="number" name="stock_total" id="bookStock" min="1" value="1"></div></div><div class="form-group" style="margin-top:14px"><label>Deskripsi</label><textarea name="description" id="bookDescription" rows="5"></textarea></div><div class="form-grid" style="margin-top:14px"><div class="form-group"><label>Cover (opsional)</label><input class="input" type="file" name="cover" accept="image/jpeg,image/png,image/webp"></div><div class="form-group"><label>File PDF (opsional)</label><input class="input" type="file" name="pdf" accept="application/pdf"></div></div><div class="form-actions"><button type="button" class="btn btn-light" data-close-book-modal>Batal</button><button class="btn btn-primary">Simpan Buku</button></div></form></div></div>
<script>
(function(){const m=document.getElementById('bookModal'),form=document.getElementById('bookForm'),set=(id,v)=>{const e=document.getElementById(id);if(e)e.value=v??'';};function open(data){window.captureModalScroll?.();m.classList.add('is-open');m.setAttribute('aria-hidden','false');window.lockPageScroll?.();if(data){document.getElementById('bookModalTitle').textContent='Edit Buku';set('bookAction','update');set('bookId',data.id);set('bookTitle',data.title);set('bookAuthor',data.author);set('bookIsbn',data.isbn);set('bookYear',data.publication_year);set('bookCategory',data.category_id);set('bookPublisher',data.publisher_id);set('bookPages',data.pages);set('bookLanguage',data.language);set('bookShelf',data.shelf_location);set('bookStock',data.stock_total);set('bookDescription',data.description);}else{document.getElementById('bookModalTitle').textContent='Tambah Buku';set('bookAction','create');set('bookId','');form.reset();set('bookAction','create');set('bookStock',1);set('bookLanguage','Indonesia');}document.getElementById('bookTitle')?.focus();}function close(){m.classList.remove('is-open');m.setAttribute('aria-hidden','true');window.unlockPageScroll?.();window.restoreModalScroll?.();}document.querySelector('[data-open-book-modal]')?.addEventListener('click',()=>open());document.querySelectorAll('[data-close-book-modal]').forEach(b=>b.addEventListener('click',close));document.querySelectorAll('[data-edit-book]').forEach(b=>b.addEventListener('click',()=>{try{open(JSON.parse(b.dataset.editBook));}catch(e){}}));m.addEventListener('click',e=>{if(e.target===m)close();});})();
</script>
<?php render_end(); ?>
